<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import FeedbackToast from '../../../src/shared/feedback/FeedbackToast.vue'
import {path,fmt} from '../data'
import {openModal,session} from '../session'
import {strategyCatalog,strategyFilters as filters,strategyAccount} from '../strategyPortfolio'
import {filterStrategies,changeStrategyStatus} from '../utils/strategyTemplates'
import {t} from '../i18n'
import StrategyCard from '../components/strategy/StrategyCard.vue'
import RecordFilter from '../components/RecordFilter.vue'
import Icon from '../components/Icon.vue'
import '../styles/strategy-fidelity.css'
const route=useRoute(),mine=computed(()=>route.params.id==='mine')
const visible=computed(()=>filterStrategies(strategyCatalog,filters.style,filters.market,filters.sort))
const sortOptions=computed(()=>['sharpe','winRate','minCapital','period'].flatMap(key=>['desc','asc'].map(order=>({value:`${key}_${order}`,label:t(`aiQuant.templates.sortBy.${key}_${order}`)}))))
const median=computed(()=>{const values=strategyCatalog.map(s=>s.sharpe).sort((a,b)=>a-b);return values[Math.floor(values.length/2)].toFixed(2)})
const records=computed(()=>session.mode==='common.demo.demo'?strategyAccount.records:[])
const total=computed(()=>records.value.filter(s=>s.status!=='completed').reduce((sum,s)=>sum+s.capital,0))
const feedback=ref(''),failure=ref(''),expanded=ref('')
function subscribe(product){openModal('strategy-subscribe',{key:'aiQuant.create.title',params:{name:product.name}},product)}
function detail(product){openModal('strategy-detail','aiQuant.detail.title',product)}
function action(record,kind){
 feedback.value='';failure.value=''
 const apply=()=>{try{changeStrategyStatus(strategyAccount,record.id,kind);feedback.value='aiQuant.actions.toast.'+kind+'Success'}catch{failure.value='aiQuant.actions.toast.'+kind+'Error'}}
 if(kind==='stop')openModal('account-confirm','aiQuant.actions.stopConfirm.title',{description:{key:'aiQuant.actions.stopConfirm.notice',params:{name:record.template.name}},focusCancel:true,confirmLabel:'aiQuant.actions.stopConfirm.confirm',onConfirm:apply})
 else apply()
}
</script>
<template>
<div class="strategy-page">
 <div class="strategy-container"><nav class="strategy-nav" :aria-label="$t('aiQuant.nav.ariaLabel')"><RouterLink :class="{active:!mine}" :to="path('/ai-quant/strategy')"><Icon name="bot"/>{{ $t('aiQuant.nav.strategy') }}</RouterLink><RouterLink :class="{active:mine}" :to="path('/ai-quant/strategy/mine')"><Icon name="chart-candlestick"/>{{ $t('aiQuant.nav.myStrategies') }}</RouterLink></nav></div>
 <template v-if="!mine">
 <section class="strategy-hero-section"><div class="strategy-container strategy-hero-grid"><div><p class="strategy-eyebrow">{{ $t('aiQuant.hero.subtitle') }}</p><h1>{{ $t('aiQuant.hero.title') }}</h1><p class="strategy-hero-description">{{ $t('aiQuant.hero.description') }}</p><div class="strategy-hero-actions"><a href="#templates" class="strategy-cta">{{ $t('aiQuant.hero.browseStrategies') }}<Icon name="arrow-right"/></a><button class="strategy-outline" @click="openModal('video','aiQuant.howItWorks.title')"><Icon name="play"/>{{ $t('aiQuant.hero.howItWorks') }}</button></div><div class="strategy-stats"><div><small>{{ $t('aiQuant.hero.statActiveFallback') }}</small><strong>{{ strategyCatalog.length }}</strong><small>{{ $t('aiQuant.hero.statActiveFallbackSub') }}</small></div><div><small>{{ $t('aiQuant.hero.statAvgSharpe') }}</small><strong>{{ median }}</strong><small>{{ $t('aiQuant.hero.statAvgSharpeSub') }}</small></div></div></div><div class="strategy-graph"><p class="strategy-eyebrow">{{ $t('aiQuant.hero.modelsRunning') }}</p><svg viewBox="0 0 480 300" role="img" :aria-label="$t('aiQuant.hero.modelsRunning')"><defs><pattern id="strategy-grid" width="72" height="56" patternUnits="userSpaceOnUse"><path d="M72 0H0V56" fill="none" stroke="#ffffff12"/></pattern><linearGradient id="strategy-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a5ff4a" stop-opacity=".13"/><stop offset="1" stop-color="#a5ff4a" stop-opacity="0"/></linearGradient></defs><rect x="20" y="20" width="440" height="260" fill="url(#strategy-grid)"/><path d="M20 230L92 200L164 168L236 136L308 104L380 72L452 40V280H20Z" fill="url(#strategy-fill)"/><path d="M20 230L452 40" fill="none" stroke="#a5ff4a" stroke-width="2"/><circle cx="452" cy="40" r="15" fill="#a5ff4a18"/><circle cx="452" cy="40" r="5" fill="#a5ff4a"/></svg></div></div></section>
 <section class="strategy-featured-section"><div class="strategy-container"><h2>{{ $t('aiQuant.sections.featured') }}</h2><p class="strategy-section-description">{{ $t('aiQuant.spotlight.subtitle') }}</p><div class="strategy-grid strategy-featured-grid"><StrategyCard v-for="index in [0,2,1]" :key="index" :product="strategyCatalog[index]" featured @detail="detail" @subscribe="subscribe"/></div></div></section>
 <section id="templates" class="strategy-catalog-section"><div class="strategy-container"><h2>{{ $t('aiQuant.templates.title') }}</h2><p class="strategy-section-description">{{ $t('aiQuant.templates.subtitle') }}</p><div class="strategy-filters"><div class="strategy-filter-group"><span>{{ $t('aiQuant.templates.filterByStyle') }}</span><button v-for="value in ['', 'conservative','balanced','aggressive']" :key="value" :aria-pressed="filters.style===(value?'aiQuant.style.'+value:'')" @click="filters.style=value?'aiQuant.style.'+value:''">{{ $t(value?'aiQuant.style.'+value:'aiQuant.templates.filterAll') }}</button></div><div class="strategy-filter-group"><span>{{ $t('aiQuant.templates.filterByMarket') }}</span><button v-for="value in ['', 'crypto','stock','forex','indices']" :key="value" :aria-pressed="filters.market===(value?'aiQuant.market.'+value:'')" @click="filters.market=value?'aiQuant.market.'+value:''">{{ $t(value?'aiQuant.market.'+value:'aiQuant.templates.filterAll') }}</button></div><div class="strategy-sort"><span>{{ $t('aiQuant.templates.sortBy.label') }}</span><RecordFilter id="strategy-sort" v-model="filters.sort" variant="field" :label="$t('aiQuant.templates.sortBy.label')" :options="sortOptions"/></div></div><div class="strategy-grid"><StrategyCard v-for="product in visible" :key="product.id" :product="product" @detail="detail" @subscribe="subscribe"/></div><p v-if="!visible.length" class="strategy-empty">{{ $t('aiQuant.templates.empty') }}</p><div class="strategy-guide"><div><h3>{{ $t('aiQuant.templates.guideCard.title') }}</h3><p>{{ $t('aiQuant.templates.guideCard.description') }}</p></div><RouterLink class="strategy-outline" :to="path('/ai-quant/quant-fund')">{{ $t('aiQuant.templates.guideCard.cta') }}<Icon name="arrow-right"/></RouterLink></div></div></section>
 <aside class="strategy-container strategy-risk"><Icon name="shield"/><div><strong>{{ $t('aiQuant.risk.title') }}</strong><p>{{ $t('aiQuant.risk.body') }}</p></div></aside>
 </template>
 <div v-else class="strategy-container strategy-mine"><h1>{{ $t('aiQuant.myStrategies.title') }}</h1><p class="strategy-section-description">{{ $t('aiQuant.strategies.subtitle') }}</p><div class="strategy-stats"><div><small>{{ $t('aiQuant.myStrategies.summary.totalCapital') }}</small><strong>{{ fmt(total) }} USDT</strong></div><div><small>{{ $t('aiQuant.myStrategies.summary.running') }}</small><strong>{{ records.filter(s=>s.status==='running').length }} / {{ records.length }}</strong></div></div><div v-if="!records.length" class="strategy-empty"><Icon name="bot"/><p>{{ $t('aiQuant.myStrategies.empty') }}</p><RouterLink class="strategy-cta" :to="path('/ai-quant/strategy')">{{ $t('aiQuant.myStrategies.browseStrategies') }}</RouterLink></div><article v-for="record in records" :key="record.id" class="strategy-record"><div class="strategy-record-heading"><h3>{{ record.template.name }}</h3><span>{{ $t('aiQuant.status.'+record.status) }}</span></div><dl class="strategy-card-facts"><div><dt>{{ $t('aiQuant.strategies.fields.capital') }}</dt><dd>{{ fmt(record.capital) }} USDT</dd></div><div><dt>{{ $t('aiQuant.strategies.fields.pnl') }}</dt><dd>{{ fmt(record.pnl) }} USDT</dd></div><div><dt>{{ $t('aiQuant.strategies.fields.endDate') }}</dt><dd>{{ new Date(record.endAt).toLocaleString() }}</dd></div><div><dt>{{ $t('aiQuant.create.takeProfitLabel') }} / {{ $t('aiQuant.create.stopLossLabel') }}</dt><dd>{{ record.takeProfit }}% / {{ record.stopLoss }}%</dd></div></dl><div class="strategy-record-actions"><button v-if="record.status==='running'" @click="action(record,'pause')">{{ $t('aiQuant.actions.pause') }}</button><button v-if="record.status==='paused'" @click="action(record,'resume')">{{ $t('aiQuant.actions.resume') }}</button><button v-if="record.status!=='completed'" @click="action(record,'stop')">{{ $t('aiQuant.actions.stop') }}</button><button :aria-expanded="expanded===record.id" @click="expanded=expanded===record.id?'':record.id">{{ $t(expanded===record.id?'aiQuant.actions.hideStats':'aiQuant.actions.viewStats') }}</button></div><p v-if="expanded===record.id" class="strategy-empty">{{ $t('aiQuant.dailyStats.empty') }}</p></article><FeedbackToast type="success" :source="()=>$t(feedback)"/><FeedbackToast :source="()=>$t(failure)"/></div>
</div>
</template>
